// Extrai e enriquece a oferta com formatação persuasiva anti-banimento
const input = $input.first().json.body || $input.first().json;

const title = input.title || 'Super Oferta Maker';
const promoPrice = Number(input.promoPrice) || 0;
const origPrice = Number(input.originalPrice) || 0;
const discount = origPrice > promoPrice ? Math.round(((origPrice - promoPrice) / origPrice) * 100) : 0;
const link = input.affiliateUrl || input.link || '';
const coupon = input.coupon ? input.coupon.toUpperCase() : '';

let lines = [];
lines.push('🖨️ OFERTA ESPECIAL: IMPRESSÃO 3D & MAKER 🧵\n');
lines.push(`📦 *${title}*\n`);

if (origPrice > promoPrice && promoPrice > 0) {
  lines.push(`❌ De: R$ ${origPrice.toFixed(2).replace('.', ',')}`);
  lines.push(`✅ Por apenas: *R$ ${promoPrice.toFixed(2).replace('.', ',')}* 🔥 (${discount}% OFF)`);
} else if (promoPrice > 0) {
  lines.push(`✅ Por apenas: *R$ ${promoPrice.toFixed(2).replace('.', ',')}* 🔥`);
}

if (coupon) {
  lines.push(`\n🎟️ CUPOM: *${coupon}*`);
  lines.push('👉 Aplique no carrinho antes de finalizar a compra!');
}

if (link) {
  lines.push(`\n🛒 Garanta no link oficial:\n👉 ${link}`);
}

lines.push('\n⚠️ Preços e estoques sujeitos a alteração pela loja.');
lines.push('\n#anúncio #GLTech3D');

return [{
  json: {
    formattedMessage: lines.join('\n'),
    imageUrl: input.imageUrl || '',
    whatsappTargetGroup: input.whatsappTargetGroup || '120363414256913914@g.us',
    telegramChatId: input.telegramChatId || '',
    raw: input
  }
}];

